	if left < right {
		return left
	}
	return right
}

func maxFloat64(left, right float64) float64 {
	if left > right {
		return left
	}
	return right
}

func derivedSearchScore(parent, proposed float64) float64 {
	return minFloat64(parent-0.01, proposed)
